  CREATE PROCEDURE [bud].[CreateBudgetAllocationRequest]      @budgetAllocationId INT,      @newAmount          DECIMAL(18,2),      @createdBy          INT,      @newRequestId       INT OUTPUT,      @message            NVARCHAR(500) OUTPUT  AS  BEGIN      SET NOCOUNT ON;      DECLARE @companyId INT, @templateId INT, @currentStageId INT, @totalStage INT;        BEGIN TRY          BEGIN TRANSACTION;            -- Validation 1: allocation exists          IF NOT EXISTS (SELECT 1 FROM bud.BudgetMonthlyAllocations WHERE allocationId = @budgetAllocationId)          BEGIN              ROLLBACK; SET @newRequestId = 0;              SET @message = 'Error: Budget Allocation ID ' + CAST(@budgetAllocationId AS NVARCHAR(10)) + ' does not exist.';              RETURN -1;          END            -- Validation 2: user exists          IF NOT EXISTS (SELECT 1 FROM dbo.jsUser WHERE userId = @createdBy)          BEGIN              ROLLBACK; SET @newRequestId = 0;              SET @message = 'Error: User ID ' + CAST(@createdBy AS NVARCHAR(10)) + ' does not exist.';              RETURN -1;          END            -- Validation 3: amount valid          IF @newAmount <= 0          BEGIN              ROLLBACK; SET @newRequestId = 0;              SET @message = 'Error: New Amount must be greater than 0.';              RETURN -1;          END            -- Create the request          INSERT INTO bud.BudgetAllocationRequest (budgetAllocationId, newAmount, createdBy, createdOn, updatedOn)          VALUES (@budgetAllocationId, @newAmount, @createdBy, GETDATE(), GETDATE());            SET @newRequestId = SCOPE_IDENTITY();            IF @newAmount > 300000          BEGIN              -- which company does this allocation belong to?              SELECT @companyId = b.company              FROM bud.BudgetMonthlyAllocations bma              JOIN bud.Budgets b ON b.budgetId = bma.budgetId              WHERE bma.allocationId = @budgetAllocationId;                -- template for budget-allocation approval (approvalId = 15)              SELECT TOP 1 @templateId = t.id              FROM jsTemplate t              JOIN jsTemplateApproval ta ON ta.templateId = t.id              WHERE ta.approvalId = 15 AND t.company = @companyId;                IF @templateId IS NULL              BEGIN                  ROLLBACK; SET @newRequestId = 0;                  SET @message = 'Error: No approval template (approvalId=15) configured for company '                               + CAST(@companyId AS NVARCHAR(10)) + '.';                  RETURN -1;              END                SELECT @totalStage = COUNT(*) FROM jsStageTemplate WHERE templateId = @templateId;                SELECT TOP 1 @currentStageId = stageId              FROM jsStageTemplate              WHERE templateId = @templateId              ORDER BY ISNULL(priority, stageId);                IF @currentStageId IS NULL              BEGIN                  ROLLBACK; SET @newRequestId = 0;                  SET @message = 'Error: Template ' + CAST(@templateId AS NVARCHAR(10)) + ' has no stages.';                  RETURN -1;              END                -- ***** THE FIX: create the workflow row *****              INSERT INTO bud.jsFlow                  (budgetAllocationRequestId, status, currentStageId, templateId, totalStage, currentStage, createdOn, updatedOn)              VALUES                  (@newRequestId, 'P', @currentStageId, @templateId, @totalStage, 1, GETDATE(), GETDATE());                SET @message = 'Success: Request ' + CAST(@newRequestId AS NVARCHAR(10))                           + ' created. Workflow initiated (template ' + CAST(@templateId AS NVARCHAR(10))                           + ', stage ' + CAST(@currentStageId AS NVARCHAR(10)) + ').';          END          ELSE          BEGIN              SET @message = 'Success: Request ' + CAST(@newRequestId AS NVARCHAR(10))                           + ' created. NO WORKFLOW (Amount <= 3 Lakh) - this request is NOT approvable.';          END            COMMIT;          RETURN 0;      END TRY      BEGIN CATCH          IF @@TRANCOUNT > 0 ROLLBACK;          SET @newRequestId = 0;          SET @message = 'Error: ' + ERROR_MESSAGE();          RETURN -1;      END CATCH  END
